def validate_number(number: str) -> str:
    if not isinstance(number, str) or len(number) == 0:
        return 'Plenty more fish in the sea'
    cleaned = ''.join(filter(lambda x: x.isdigit() or x == '+', number))
    if cleaned.startswith('+44') and len(cleaned) == 13 and cleaned[3:].isdigit():
        return 'In with a chance'
    if cleaned.startswith('07') and len(cleaned) == 11 and cleaned[2:].isdigit():
        return 'In with a chance'
    return 'Plenty more fish in the sea'
